import * as THREE from 'https://cdn.jsdelivr.net/npm/three@0.166.1/build/three.module.js';

const canvas = document.querySelector('#scene');
const renderer = new THREE.WebGLRenderer({ canvas, antialias: true, powerPreference: 'high-performance' });
renderer.setPixelRatio(Math.min(devicePixelRatio, 1.7));
renderer.setSize(innerWidth, innerHeight);
renderer.shadowMap.enabled = true;
renderer.shadowMap.type = THREE.PCFSoftShadowMap;
renderer.outputColorSpace = THREE.SRGBColorSpace;
renderer.toneMapping = THREE.ACESFilmicToneMapping;
renderer.toneMappingExposure = 1.12;
const scene = new THREE.Scene();
scene.background = new THREE.Color('#8dd5e8');
scene.fog = new THREE.Fog('#a9e3dc', 105, 250);
const camera = new THREE.PerspectiveCamera(54, innerWidth / innerHeight, .1, 420);
const hemi = new THREE.HemisphereLight('#e5fbff', '#759d52', 2.0); scene.add(hemi);
const sun = new THREE.DirectionalLight('#fff1cf', 3.2); sun.position.set(-55, 85, 30); sun.castShadow = true;
sun.shadow.mapSize.set(2048, 2048); sun.shadow.camera.left = -110; sun.shadow.camera.right = 110; sun.shadow.camera.top = 110; sun.shadow.camera.bottom = -110; sun.shadow.bias = -.0004; scene.add(sun);

const mat = (color, roughness=.8, metalness=0) => new THREE.MeshStandardMaterial({ color, roughness, metalness });
const grassMat=mat('#7fc47a'), roadMat=mat('#555c62',.94), whiteMat=mat('#fff4d7'), curbRed=mat('#fa725b'), darkMat=mat('#26323a'), tireMat=mat('#20282b'), goldMat=mat('#ffd55e',.38), leafMats=['#3c9b70','#57b878','#88cb72','#318c67'].map(c=>mat(c)), flowerMats=['#f5db72','#f5a2a3','#fff8dc'].map(c=>mat(c));
const ground = new THREE.Mesh(new THREE.PlaneGeometry(800,800), grassMat); ground.rotation.x=-Math.PI/2; ground.position.y=-1.05; ground.receiveShadow=true; scene.add(ground);

// A wide, flowing spline makes the complete circuit.
const trackPoints = [new THREE.Vector3(-39,0,-32),new THREE.Vector3(-18,0,-43),new THREE.Vector3(12,0,-44),new THREE.Vector3(37,0,-34),new THREE.Vector3(47,0,-17),new THREE.Vector3(43,0,0),new THREE.Vector3(29,0,9),new THREE.Vector3(13,0,5),new THREE.Vector3(4,0,12),new THREE.Vector3(12,0,27),new THREE.Vector3(5,0,42),new THREE.Vector3(-13,0,47),new THREE.Vector3(-34,0,38),new THREE.Vector3(-47,0,21),new THREE.Vector3(-47,0,3),new THREE.Vector3(-36,0,-10),new THREE.Vector3(-20,0,-13),new THREE.Vector3(-10,0,-21),new THREE.Vector3(-16,0,-35)];
const curve = new THREE.CatmullRomCurve3(trackPoints, true, 'catmullrom', .25);
const TRACK_N=520, ROAD_W=12, roadSamples=curve.getSpacedPoints(TRACK_N);
function roadPoint(t){return curve.getPointAt(((t%1)+1)%1)}
function sideAt(t){const tangent=curve.getTangentAt(((t%1)+1)%1);return new THREE.Vector3(tangent.z,0,-tangent.x).normalize()}
function ribbon(width, y, material, offset=0){const positions=[],indices=[];for(let i=0;i<=TRACK_N;i++){let t=i/TRACK_N,p=roadPoint(t),s=sideAt(t);p.y=y;positions.push(p.x+s.x*(width/2+offset),y,p.z+s.z*(width/2+offset),p.x-s.x*(width/2+offset),y,p.z-s.z*(width/2+offset));if(i<TRACK_N){let a=i*2;indices.push(a,a+1,a+2,a+1,a+3,a+2)}}const geo=new THREE.BufferGeometry();geo.setAttribute('position',new THREE.Float32BufferAttribute(positions,3));geo.setIndex(indices);geo.computeVertexNormals();let mesh=new THREE.Mesh(geo,material);mesh.receiveShadow=true;scene.add(mesh);return mesh}
ribbon(ROAD_W+3,-.72,mat('#d6bd91'));
ribbon(ROAD_W,-.66,roadMat);
// Alternating curb blocks along both track edges.
for(let i=0;i<TRACK_N;i+=4){const t=i/TRACK_N,p=roadPoint(t),s=sideAt(t),t2=(i+4)/TRACK_N,p2=roadPoint(t2),s2=sideAt(t2);for(const side of [-1,1]){const verts=[];for(const [q,v] of [[p,s],[p2,s2]]){verts.push(q.x+v.x*(ROAD_W/2+.24)*side,-.59,q.z+v.z*(ROAD_W/2+.24)*side,q.x+v.x*(ROAD_W/2+1.02)*side,-.59,q.z+v.z*(ROAD_W/2+1.02)*side)}const g=new THREE.BufferGeometry();g.setAttribute('position',new THREE.Float32BufferAttribute(verts,3));g.setIndex([0,2,1,1,2,3]);g.computeVertexNormals();scene.add(new THREE.Mesh(g,Math.floor(i/4)%2?whiteMat:curbRed));}}
// Start stripe, grandstand arch, and gentle rolling landscape accents.
const startP=roadPoint(0),startSide=sideAt(0),startTan=curve.getTangentAt(0);
const stripe=new THREE.Mesh(new THREE.PlaneGeometry(ROAD_W,1.15),whiteMat);stripe.rotation.x=-Math.PI/2;stripe.rotation.z=Math.atan2(startTan.x,startTan.z);stripe.position.set(startP.x,-.54,startP.z);scene.add(stripe);
function box(parent,geo,material,pos,rot){const m=new THREE.Mesh(geo,material);m.position.set(...pos);if(rot)m.rotation.set(...rot);m.castShadow=true;m.receiveShadow=true;parent.add(m);return m}
const arch=new THREE.Group();const archMat=mat('#fff4d8'), coral=mat('#f77b5d');
box(arch,new THREE.BoxGeometry(.8,8,.8),archMat,[-ROAD_W/2-1.6,3.2,0]);box(arch,new THREE.BoxGeometry(.8,8,.8),archMat,[ROAD_W/2+1.6,3.2,0]);box(arch,new THREE.BoxGeometry(ROAD_W+4.8,1.2,.9),coral,[0,7.3,0]);box(arch,new THREE.BoxGeometry(ROAD_W+2, .28,1.1),goldMat,[0,6.45,0]);arch.position.set(startP.x,-.55,startP.z);arch.rotation.y=Math.atan2(startTan.x,startTan.z);scene.add(arch);
// Soft distant hills make the horizon feel like a bright countryside.
for(let i=0;i<14;i++){const a=i/14*Math.PI*2,r=118+Math.sin(i*12)*8;const h=17+(i%4)*5;const hill=new THREE.Mesh(new THREE.SphereGeometry(1,16,10),mat(i%2?'#9bd69e':'#8acc91'));hill.scale.set(30,h,24);hill.position.set(Math.sin(a)*r,h-2,Math.cos(a)*r);hill.castShadow=true;scene.add(hill)}
// Stylized trees and flower patches around the course.
const trunkMat=mat('#8c6244');
function makeTree(x,z,scale=1){const group=new THREE.Group();box(group,new THREE.CylinderGeometry(.28,.42,3.3,7),trunkMat,[0,1.1,0]);for(let j=0;j<3;j++){const m=new THREE.Mesh(new THREE.IcosahedronGeometry(1,1),leafMats[(j+Math.floor(x+z+100))%leafMats.length]);m.position.set(0,2.4+j*.72,0);m.scale.set(1.7-j*.25,1.35,1.55-j*.18);m.castShadow=true;group.add(m)}group.position.set(x,0,z);group.scale.setScalar(scale);scene.add(group)}
for(let i=0;i<62;i++){const a=i*2.399963;const r=59+(i%5)*7;const x=Math.cos(a)*r,z=Math.sin(a)*r;if(Math.abs(x)<53&&Math.abs(z)<51&&Math.abs(x)>21)makeTree(x,z,.72+(i%4)*.1)}
const flowerGeo=new THREE.SphereGeometry(.18,7,5);
for(let i=0;i<160;i++){const a=i*2.4,r=22+(i*7%40),x=Math.cos(a)*r,z=Math.sin(a)*r;if(Math.hypot(x,z)>53){const f=new THREE.Mesh(flowerGeo,flowerMats[i%3]);f.position.set(x,-.25,z);f.scale.y=.35;scene.add(f)}}
// Decorative direction arrows and landmark boards.
const signMat=mat('#fff7df'), signText=mat('#ef7659');
for(let i=0;i<8;i++){const t=(i+.13)/8,p=roadPoint(t),s=sideAt(t),x=p.x+s.x*10,z=p.z+s.z*10;const post=box(scene,new THREE.CylinderGeometry(.12,.16,2,7),archMat,[x,0,z]);const board=box(scene,new THREE.BoxGeometry(2.4,1.25,.25),signMat,[x,1.3,z]);const arrow=box(scene,new THREE.ConeGeometry(.37,.75,3),signText,[x,1.3,z+.17],[0,0,-Math.PI/2]);}

// The little racer: bright shell, chunky tires, and a tiny helmeted driver.
const kart=new THREE.Group();const shell=mat('#f25849',.42), shellLight=mat('#ff8c67',.38), seatMat=mat('#713d45'), skin=mat('#ffc58f'), helmet=mat('#f5c947',.35), blueMat=mat('#48a9c2',.4);
box(kart,new THREE.BoxGeometry(2.45,.58,3.55),shell,[0,.78,0]);box(kart,new THREE.BoxGeometry(2.08,.32,1.8),shellLight,[0,1.08,-.05]);box(kart,new THREE.BoxGeometry(1.55,.62,1.05),seatMat,[0,1.28,-.43]);
const nose=box(kart,new THREE.BoxGeometry(1.7,.3,.85),goldMat,[0,1.05,1.47]);
for(const x of [-.78,.78]){box(kart,new THREE.BoxGeometry(.37,.2,.08),whiteMat,[x,1.04,1.9]);box(kart,new THREE.BoxGeometry(.34,.2,.08),curbRed,[x,1.04,1.99]);}
// Driver torso and head
box(kart,new THREE.CylinderGeometry(.42,.52,.9,9),blueMat,[0,1.77,-.32]);
const head=new THREE.Group();const face=new THREE.Mesh(new THREE.SphereGeometry(.48,16,12),skin);face.position.y=2.35;head.add(face);const cap=new THREE.Mesh(new THREE.SphereGeometry(.52,16,10,0,Math.PI*2,0,Math.PI*.52),helmet);cap.position.y=2.55;head.add(cap);box(head,new THREE.BoxGeometry(.72,.15,.68),helmet,[0,2.38,.05]);
for(const x of [-.17,.17]){const eye=new THREE.Mesh(new THREE.SphereGeometry(.055,8,6),darkMat);eye.position.set(x,2.34,.43);head.add(eye)}kart.add(head);
const wheels=[];const wheelGeo=new THREE.CylinderGeometry(.44,.44,.36,16);wheelGeo.rotateZ(Math.PI/2);
for(const x of [-1.23,1.23])for(const z of [-1.08,1.13]){const wheel=new THREE.Mesh(wheelGeo,tireMat);wheel.position.set(x,.47,z);wheel.castShadow=true;kart.add(wheel);const hub=new THREE.Mesh(new THREE.CylinderGeometry(.2,.2,.38,12),goldMat);hub.rotation.z=Math.PI/2;hub.position.set(x,.47,z);kart.add(hub);wheels.push({wheel,front:z>0})}
kart.traverse(o=>{if(o.isMesh){o.castShadow=true;o.receiveShadow=true}});scene.add(kart);

// Puffy clouds float above the far hills.
const cloudMat=new THREE.MeshStandardMaterial({color:'#fffdf3',roughness:1,transparent:true,opacity:.8});
for(let i=0;i<11;i++){const cloud=new THREE.Group();const x=-105+(i*37)%210,z=-100+((i*61)%200);for(let j=0;j<4;j++){const puff=new THREE.Mesh(new THREE.SphereGeometry(1,12,8),cloudMat);puff.scale.set(5+j%2*2,2.6,3);puff.position.set(j*3.2-4,0,(j%2)*1.3);cloud.add(puff)}cloud.position.set(x,32+(i%3)*8,z);cloud.userData.seed=i;scene.add(cloud)}

const $=s=>document.querySelector(s), timeEl=$('#timeLeft'),timerBar=$('#timerBar'),speedEl=$('#speedValue'),speedBar=$('#speedBar'),lapEl=$('#lapNumber'),mapDot=$('#mapDot');
const startOverlay=$('#startOverlay'),finishOverlay=$('#finishOverlay'),countdownEl=$('#countdown');
let best=Number(localStorage.getItem('turboToadBest')||0);$('#bestScore').textContent=best?`${best} LAPS`:'— LAPS';
let mode='ready',timeLeft=60,speed=0,yaw=0,steer=0,lapCount=0,progress=0,prevProgress=0,lapStart=0,bestLap=Infinity,topSpeed=0,driftCharge=0,boostTime=0,elapsed=0,toastTimer=0;
const keys={};
function setStartPosition(){const tangent=curve.getTangentAt(0);yaw=Math.atan2(tangent.x,tangent.z);kart.position.set(startP.x-tangent.x*5,0,startP.z-tangent.z*5);kart.rotation.y=yaw;prevProgress=.99;progress=.99;}
setStartPosition();
function nearestTrack(){let bestD=Infinity,bestI=0;for(let i=0;i<TRACK_N;i+=2){const p=roadSamples[i],dx=kart.position.x-p.x,dz=kart.position.z-p.z,d=dx*dx+dz*dz;if(d<bestD){bestD=d;bestI=i}}return {t:bestI/TRACK_N,d:Math.sqrt(bestD),index:bestI}}
function showToast(text){const t=$('#toast');t.innerHTML=`${text} <span>✦</span>`;t.classList.add('show');toastTimer=1.2}
function startRace(){if(mode==='countdown'||mode==='playing')return;mode='countdown';startOverlay.hidden=true;finishOverlay.hidden=true;timeLeft=60;lapCount=0;speed=0;topSpeed=0;bestLap=Infinity;lapStart=0;elapsed=0;setStartPosition();let n=3;countdownEl.hidden=false;countdownEl.textContent=n;if(soundOn)beep(440,.07);const tick=()=>{if(mode!=='countdown')return;n--;if(n>0){countdownEl.textContent=n;if(soundOn)beep(440,.07);setTimeout(tick,700)}else{countdownEl.textContent='GO!';if(soundOn)beep(720,.16);setTimeout(()=>{if(mode==='countdown'){countdownEl.hidden=true;mode='playing'}},450)}};setTimeout(tick,700)}
$('#startButton').addEventListener('click',startRace);$('#againButton').addEventListener('click',startRace);
function finishRace(){mode='finished';speed=0;$('#finalLaps').textContent=lapCount;$('#finalBest').textContent=Number.isFinite(bestLap)?formatTime(bestLap):'—:—';$('#finalSpeed').textContent=Math.round(topSpeed*3.6);if(lapCount>best){best=lapCount;localStorage.setItem('turboToadBest',best);$('#bestScore').textContent=`${best} LAPS`}finishOverlay.hidden=false;}
function formatTime(s){return `${Math.floor(s/60)}:${(s%60).toFixed(2).padStart(5,'0')}`}

// Optional tiny synth engine; it only starts after the player's first click.
let soundOn=true,audioCtx=null,engineOsc=null,engineGain=null;
function initAudio(){if(!audioCtx){audioCtx=new (window.AudioContext||window.webkitAudioContext)();engineOsc=audioCtx.createOscillator();engineGain=audioCtx.createGain();engineOsc.type='sawtooth';engineGain.gain.value=0;engineOsc.connect(engineGain);engineGain.connect(audioCtx.destination);engineOsc.start()}}
function beep(freq,duration){try{initAudio();const o=audioCtx.createOscillator(),g=audioCtx.createGain();o.frequency.value=freq;o.type='sine';g.gain.setValueAtTime(.08,audioCtx.currentTime);g.gain.exponentialRampToValueAtTime(.001,audioCtx.currentTime+duration);o.connect(g);g.connect(audioCtx.destination);o.start();o.stop(audioCtx.currentTime+duration)}catch{}}
$('#soundToggle').addEventListener('click',()=>{$('#soundToggle').classList.toggle('muted');soundOn=!soundOn;$('#soundToggle').innerHTML=`♪ <span>SOUND ${soundOn?'ON':'OFF'}</span>`;if(!soundOn&&engineGain)engineGain.gain.value=0;if(soundOn&&mode==='playing')initAudio()});
window.addEventListener('keydown',e=>{const key=e.key.toLowerCase();if([' ','arrowup','arrowdown','arrowleft','arrowright'].includes(key))e.preventDefault();keys[key]=true;if(key==='r'&&mode==='playing'){setStartPosition();speed=0}});
window.addEventListener('keyup',e=>{keys[e.key.toLowerCase()]=false});
for(const btn of document.querySelectorAll('.mobile-controls button')){const k=btn.dataset.key;const down=e=>{e.preventDefault();keys[`touch_${k}`]=true};const up=e=>{e.preventDefault();keys[`touch_${k}`]=false};btn.addEventListener('pointerdown',down);btn.addEventListener('pointerup',up);btn.addEventListener('pointercancel',up);btn.addEventListener('pointerleave',up)}
function input(){const left=keys.a||keys.arrowleft||keys.touch_left,right=keys.d||keys.arrowright||keys.touch_right,gas=keys.w||keys.arrowup||keys.touch_gas,reverse=keys.s||keys.arrowdown,drift=keys[' ']||keys.touch_drift;return {turn:(right?1:0)-(left?1:0),gas:gas?1:0,reverse:reverse?1:0,drift:!!drift}}

