// Arcade handling: accelerate hard, scrub speed on grass, and release a charged drift for a burst.
setStartPosition();kart.position.y=-.66;
const clock=new THREE.Clock();let cameraReady=false;
function update(dt){elapsed+=dt;if(mode==='playing'){timeLeft=Math.max(0,timeLeft-dt);if(timeLeft<=0)finishRace()}
const controls=input();if(mode==='playing'){
 const onRoad=nearestTrack(),grass=onRoad.d>ROAD_W*.52;
 if(controls.gas)speed+=16.5*dt;else if(controls.reverse&&speed>1)speed-=23*dt;else if(controls.reverse)speed-=8*dt;else speed-=2.2*dt;
 if(grass)speed-=Math.min(speed,5.5*dt);
 if(boostTime>0){boostTime-=dt;speed+=13*dt}
 speed=THREE.MathUtils.clamp(speed,-5,boostTime>0?34:27);
 const steering=controls.turn;const grip=grass?.68:1;
 yaw+=steering*dt*(.28+Math.min(Math.abs(speed)/13,1.4))*grip*(speed<-.1?-1:1);
 if(controls.drift&&Math.abs(steering)>.2&&Math.abs(speed)>7){driftCharge=Math.min(1.3,driftCharge+dt);yaw+=steering*dt*.36}
 else if(driftCharge>.36){boostTime=.72;driftCharge=0;showToast('DRIFT BOOST!');if(soundOn)beep(680,.13)}else driftCharge=Math.max(0,driftCharge-dt*.7);
 const forwardX=Math.sin(yaw),forwardZ=Math.cos(yaw);
 kart.position.x+=forwardX*speed*dt;kart.position.z+=forwardZ*speed*dt;
 // A forgiving out-of-bounds rebound nudges the kart back toward the circuit.
 if(onRoad.d>ROAD_W*1.25){const p=roadPoint(onRoad.t),dx=p.x-kart.position.x,dz=p.z-kart.position.z; kart.position.x+=dx*dt*.65;kart.position.z+=dz*dt*.65;speed=Math.max(speed,0)}
 kart.rotation.y=yaw;kart.rotation.z=THREE.MathUtils.lerp(kart.rotation.z,-steering*Math.min(Math.abs(speed)/28,.14),Math.min(1,dt*7));
 kart.position.y=-.66+Math.sin(elapsed*18)*Math.min(Math.abs(speed)/220,.045);head.rotation.z=-steering*.07;
 for(const w of wheels){w.wheel.rotation.x+=speed*dt*1.9;if(w.front)w.wheel.rotation.y=THREE.MathUtils.lerp(w.wheel.rotation.y,-steering*.32,dt*8)}
 const near=nearestTrack();progress=near.t;
 if(prevProgress>.88&&progress<.12&&elapsed>2){lapCount++;const lapTime=elapsed-lapStart;lapStart=elapsed;if(lapTime>4)bestLap=Math.min(bestLap,lapTime);if(soundOn)beep(880,.2)}prevProgress=progress;
 topSpeed=Math.max(topSpeed,speed);
 // Name the stretch currently under the racer.
 const sections=['START / FINISH','SUNFLOWER STRAIGHT','MUSHROOM BEND','CLOVER CHICANE','PEACH ORCHARD'];$('#placeName').textContent=sections[Math.floor(progress*sections.length)%sections.length];
 const angle=progress*Math.PI*2;const mx=85+Math.cos(angle)*49,m y=0;
 mapDot.setAttribute('cx',THREE.MathUtils.clamp(85+kart.position.x*1.18,19,151).toFixed(1));mapDot.setAttribute('cy',THREE.MathUtils.clamp(54+kart.position.z*1.0,14,97).toFixed(1));
}
// Soft chase cam keeps the road visible and leans slightly through turns.
const back=new THREE.Vector3(-Math.sin(yaw),0,-Math.cos(yaw));const desired=new THREE.Vector3(kart.position.x+back.x*11,kart.position.y+6.6,kart.position.z+back.z*11);camera.position.lerp(desired,1-Math.pow(.001,dt));const look=new THREE.Vector3(kart.position.x+Math.sin(yaw)*8,kart.position.y+1.3,kart.position.z+Math.cos(yaw)*8);camera.lookAt(look);cameraReady=true;
for(const c of scene.children){if(c.userData.seed!==undefined)c.position.x+=Math.sin(elapsed*.12+c.userData.seed)*dt*.35}
// HUD updates during countdown and the finish transition too.
const shown=Math.max(0,timeLeft);timeEl.innerHTML=`${Math.ceil(shown).toString().padStart(2,'0')}<span>.${Math.floor((shown%1)*10)}</span>`;timerBar.style.width=`${shown/60*100}%`;timerBar.style.background=shown<10?'#f04c43':'#ff7959';speedEl.innerHTML=`${Math.max(0,Math.round(speed*3.6)).toString().padStart(3,'0')} <small>KM/H</small>`;speedBar.style.width=`${Math.min(100,Math.max(0,speed)/34*100)}%`;lapEl.textContent=lapCount+1;
if(toastTimer>0){toastTimer-=dt;if(toastTimer<=0)$('#toast').classList.remove('show')}
if(soundOn&&engineGain&&audioCtx){const vol=mode==='playing'?.012+Math.max(0,speed)/34*.025:0;engineGain.gain.setTargetAtTime(vol,audioCtx.currentTime,.08);engineOsc.frequency.setTargetAtTime(58+Math.max(0,speed)*5,audioCtx.currentTime,.06)}
}
function render(){const dt=Math.min(clock.getDelta(),.05);update(dt);renderer.render(scene,camera);requestAnimationFrame(render)}render();
window.addEventListener('resize',()=>{camera.aspect=innerWidth/innerHeight;camera.updateProjectionMatrix();renderer.setSize(innerWidth,innerHeight);renderer.setPixelRatio(Math.min(devicePixelRatio,1.7))});

